/** Ambil label marketplace untuk bahasa aktif (fallback ke Indonesia). */
export function getMarketplaceLabels(language: string): Record<string, string> {
  return dictMarketplace[language] ?? dictMarketplace.id;
}

/** Daftar kunci marketplace (untuk validasi kelengkapan terjemahan). */
export const MARKETPLACE_KEYS = Object.keys(dictMarketplace.id);
